source("/private/tmp/claude-501/-Users-pbtz-src-github-com-pedrobtz-zuspark/23786a96-505c-4b1e-b66f-e320fa1ada7b/scratchpad/hunt/hunt-2/harness.R")
conv <- function(title, cnd) {
  cat("##", title, "\n")
  r <- tryCatch(zuspark:::as_zuspark_error(cnd), error = function(e) { cat("   CONVERSION FAILED:", conditionMessage(e), "\n"); NULL }, warning = function(w) { cat("   WARNING:", conditionMessage(w), "\n"); NULL })
  if (!is.null(r)) { cat("   class:", paste(class(r), collapse = " "), "\n   msg:", conditionMessage(r), "\n"); str(unclass(r)[setdiff(names(r), c("message", "call", "parent", "con"))], give.attr = FALSE) }
  invisible(r)
}
conv("status without details", status_cnd("INTERNAL", "x"))
e <- spark_cnd(); conv("spark error", e)
e <- spark_cnd(); e$details$details <- list(ErrorInfo = list(reason = "r", domain = "com.other", metadata = c(errorClass = "A")), ErrorInfo = e$details$details$ErrorInfo); conv("two ErrorInfo, Spark's second", e)
e <- spark_cnd(); e$details$details <- c(list(DebugInfo = list(detail = "x")), e$details$details); conv("DebugInfo then ErrorInfo", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata <- NULL; conv("ErrorInfo without metadata", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata <- list(errorClass = "A", sqlState = "1"); conv("metadata as list", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata <- character(); conv("metadata empty", e)
e <- spark_cnd(); e$grpc_message <- ""; conv("empty grpc_message", e)
e <- spark_cnd(); e$grpc_message <- NULL; e$details$message <- NULL; conv("no grpc_message nor details message", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata[["messageParameters"]] <- "{\"a\":\"b \\\"q\\\" c\",\"n\":\"1\",\"u\":\"\\u00e9\"}"; r <- conv("params w/ escapes", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata[["messageParameters"]] <- "{\"a\":null,\"b\":\"x\"}"; conv("params with null value", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata[["messageParameters"]] <- "{\"a\":\"\",\"b\":\"x\"}"; conv("params with empty value", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata[["messageParameters"]] <- "{\"a\":[\"x\",\"y\"],\"b\":\"z\"}"; conv("params with nested array", e)
e <- spark_cnd(); e$details$details$ErrorInfo$metadata[["messageParameters"]] <- "{\"a\":1,\"b\":\"z\"}"; conv("params with number", e)
e <- spark_cnd(); e$details$details$ErrorInfo$domain <- NULL; conv("ErrorInfo no domain", e)
e <- structure(class = c("zugrpc_error_interrupt", "zugrpc_error", "error", "condition"), list(message = "The call was interrupted.", call = NULL, grpc_status = "CANCELLED")); conv("interrupt", e)
e <- status_cnd("INTERNAL"); e$details <- "raw-string"; conv("details atomic", e)
